SELECT * FROM (SELECT if(isNull(_num_value) OR isNull(_den_value) OR _den_value = 0, NULL, _num_value / _den_value) AS value, bucket, _dim_0 FROM (SELECT if((SELECT count() FROM (SELECT 1 FROM logs WHERE service_name = 'arena' AND timestamp <= now() - INTERVAL 3600 SECOND LIMIT 1)) > 0, if(isNull(max(num_present)), 0, max(numerator)), NULL) AS _num_value, max(denominator) AS _den_value, bucket, _dim_0 FROM (SELECT toNullable(value) AS numerator, NULL AS denominator, 1 AS num_present, bucket, _dim_0 FROM (SELECT * FROM (SELECT * FROM (SELECT count() AS value, bucket, _dim_0 FROM (SELECT NULL AS _metric_value, toStartOfInterval(timestamp, INTERVAL 300 SECOND) AS bucket, attributes['source'] AS _dim_0 FROM logs WHERE service_name = 'arena' AND timestamp >= now() - INTERVAL 3600 SECOND AND attributes['event_type'] = 'game_completed') AS _source WHERE (SELECT count() FROM (SELECT 1 FROM logs WHERE service_name = 'arena' AND timestamp <= now() - INTERVAL 3600 SECOND LIMIT 1)) > 0 GROUP BY bucket, _dim_0) AS _grouped ORDER BY bucket DESC LIMIT 50000) AS _recent ORDER BY bucket, _dim_0 LIMIT 50000) UNION ALL SELECT NULL AS numerator, toNullable(value) AS denominator, NULL AS num_present, bucket, _dim_0 FROM (SELECT * FROM (SELECT * FROM (SELECT count() AS value, bucket, _dim_0 FROM (SELECT NULL AS _metric_value, toStartOfInterval(timestamp, INTERVAL 300 SECOND) AS bucket, attributes['source'] AS _dim_0 FROM logs WHERE service_name = 'arena' AND timestamp >= now() - INTERVAL 3600 SECOND AND attributes['event_type'] = 'game_started') AS _source WHERE (SELECT count() FROM (SELECT 1 FROM logs WHERE service_name = 'arena' AND timestamp <= now() - INTERVAL 3600 SECOND LIMIT 1)) > 0 GROUP BY bucket, _dim_0) AS _grouped ORDER BY bucket DESC LIMIT 50000) AS _recent ORDER BY bucket, _dim_0 LIMIT 50000)) AS _combined GROUP BY bucket, _dim_0 ORDER BY bucket DESC LIMIT 50000) AS _ratios ORDER BY bucket DESC LIMIT 50000) AS _recent ORDER BY bucket, _dim_0 LIMIT 50000
